<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/api/third_party_register_core.php';
function tpr_ok(bool $ok,string $message):void {if(!$ok)throw new RuntimeException($message);}
function tpr_reject(callable $fn,string $why):void {try{$fn();}catch(InvalidArgumentException){return;}throw new RuntimeException($why);}
$user=['id'=>1,'full_name'=>'Register fixture'];$body=['action'=>'create','requestKey'=>'register-fixture-00001','date'=>'2026-10-28','amount'=>'1234.50','currency'=>'PKR','receivedFrom'=>'Customer fixture','paidTo'=>'Freight fixture','category'=>'Freight Forwarder','reference'=>'CHEQUE-10','notes'=>'Information only'];$store=['revision'=>0,'rows'=>[]];
$r=tpr_change($store,$body,$user,'TTI');$row=$r['record'];tpr_ok($row['amount']===1234.5&&$row['entity']==='TTI'&&count($r['store']['rows'])===1,'Standalone register saves actual fields');tpr_ok(array_keys($r['store'])===['revision','rows'],'No financial collections are created');$retry=tpr_change($r['store'],$body,$user,'TTI');tpr_ok($retry['duplicate']&&$retry['store']===$r['store'],'Lost acknowledgement retry must not duplicate the register record');
$changed=$body;$changed['amount']=99;tpr_reject(fn()=>tpr_change($r['store'],$changed,$user,'TTI'),'Changed retry refused');
foreach([['amount'=>0],['amount'=>-1],['amount'=>'NaN'],['amount'=>INF],['date'=>'2026-02-30'],['receivedFrom'=>''],['paidTo'=>''],['currency'=>'XXX'],['category'=>'Unknown']] as $patch)tpr_reject(fn()=>tpr_change($store,array_replace($body,$patch),$user,'TTI'),'Invalid register data accepted');
tpr_reject(fn()=>tpr_change($store,$body+['journalId'=>'DO-NOT-POST'],$user,'TTI'),'Accounting fields must not be accepted');
$edit=array_replace($body,['action'=>'edit','id'=>$row['id'],'version'=>1,'reason'=>'Correct recipient','paidTo'=>'Supplier fixture','category'=>'Supplier']);unset($edit['requestKey']);$edited=tpr_change($r['store'],$edit,$user,'TTI');tpr_ok($edited['record']['version']===2&&count($edited['record']['history'])===1,'Explicit edit retains the original information');tpr_reject(fn()=>tpr_change($edited['store'],$edit,$user,'TTI'),'Stale edit rejected');tpr_reject(fn()=>tpr_change($r['store'],$edit,$user,'BRM'),'Cross-company edit rejected');tpr_ok(tpr_public($edited['store'],'BRM')===[],'Company records are isolated');
$public=tpr_public($edited['store'],'TTI')[0];tpr_ok(!array_intersect(['history','requestKey','requestFingerprint'],array_keys($public)),'Private save/audit metadata is not in the row list');$delete=['action'=>'delete','id'=>$row['id'],'version'=>2,'reason'=>'Duplicate information'];$deleted=tpr_change($edited['store'],$delete,$user,'TTI');tpr_ok(tpr_public($deleted['store'],'TTI')===[]&&$deleted['record']['history'][1]['before']['paidTo']==='Supplier fixture','Delete hides the record and retains history');tpr_ok($store===['revision'=>0,'rows'=>[]],'Core never mutates the caller data');
echo "PASS standalone third-party register fields, validation, duplicate retry, amendments, company isolation and no accounting collections\n";
